INSERT INTO books (serial_no, title, user_id, genre_id, language, synopsis, cover, status, price, views, created_at) VALUES
('NB-000001', 'The Last Lantern', 5, 1, 'English', 'When every light in the kingdom goes out, a lamplighter''s apprentice discovers she carries the last flame that can rekindle them, and every faction wants it.', '/images/covers/nb-000001.svg', 'ongoing', 4.99, 27400000, datetime('now', 'localtime', '-100 days')),
('NB-000002', 'Iron Tide', 3, 2, 'English', 'A disgraced naval officer returns to the sea at the helm of a stolen warship, hunting the admiral who sank his fleet.', '/images/covers/nb-000002.svg', 'ongoing', 5.99, 15200000, datetime('now', 'localtime', '-97 days')),
('NB-000003', 'Letters to Autumn', 4, 3, 'English', 'Two strangers swap letters through a library book left on the same shelf, never knowing they live on the same street.', '/images/covers/nb-000003.svg', 'completed', 3.99, 9800000, datetime('now', 'localtime', '-94 days')),
('NB-000004', 'The Clockmaker''s Secret', 5, 5, 'English', 'A clockmaker is found dead inside a locked tower, and every clock in the city has stopped at the same minute.', '/images/covers/nb-000004.svg', 'completed', 4.49, 6100000, datetime('now', 'localtime', '-91 days')),
('NB-000005', 'Starbound', 2, 6, 'English', 'The crew of a salvage freighter answers a distress call from a ship that disappeared three hundred years ago.', '/images/covers/nb-000005.svg', 'ongoing', 5.49, 4400000, datetime('now', 'localtime', '-88 days')),
('NB-000006', 'Ashen Crown', 3, 4, 'English', 'A runaway prince crosses the burnt wastes to reclaim a crown that turns to ash in the hands of anyone unworthy.', '/images/covers/nb-000006.svg', 'ongoing', 4.99, 2900000, datetime('now', 'localtime', '-85 days')),
('NB-000007', 'Whispering Pines', 4, 8, 'English', 'Campers at a lakeside retreat begin to hear their own voices calling from the forest at night.', '/images/covers/nb-000007.svg', 'completed', 2.99, 1700000, datetime('now', 'localtime', '-82 days')),
('NB-000008', 'System Restart', 2, 7, 'English', 'A burnt-out programmer wakes up inside the game he was fired from, and the admin console still answers to him.', '/images/covers/nb-000008.svg', 'ongoing', 3.49, 980500, datetime('now', 'localtime', '-79 days')),
('NB-000009', 'The Sword Saint Who Refused to Retire', 5, 2, 'English', 'At ninety, the empire''s greatest swordsman is told to step aside. He opens a dojo instead, for the students nobody else will train.', '/images/covers/nb-000009.svg', 'ongoing', 4.99, 642300, datetime('now', 'localtime', '-76 days')),
('NB-000010', 'Moonlit Bakery', 4, 10, 'English', 'A bakery that only opens after midnight serves pastries that let customers relive one good memory.', '/images/covers/nb-000010.svg', 'ongoing', 1.99, 410800, datetime('now', 'localtime', '-73 days')),
('NB-000011', 'Dungeon Diner', 2, 9, 'English', 'An ex-adventurer opens a restaurant on the fifth floor of a dungeon. The monsters become her best customers.', '/images/covers/nb-000011.svg', 'ongoing', 2.49, 355000, datetime('now', 'localtime', '-70 days')),
('NB-000012', 'Echoes of Atlantis', 3, 4, 'English', 'A marine archaeologist finds a door on the sea floor that opens onto a city still very much alive.', '/images/covers/nb-000012.svg', 'completed', 4.99, 298000, datetime('now', 'localtime', '-67 days')),
('NB-000013', 'Academy of Thorns', 5, 1, 'English', 'The only student without magic at a school for mages must survive a year of duels by being cleverer than everyone else.', '/images/covers/nb-000013.svg', 'ongoing', 3.99, 254000, datetime('now', 'localtime', '-64 days')),
('NB-000014', 'Neon Detective', 2, 5, 'English', 'In a city where memories can be bought, a detective investigates a murder that nobody can remember.', '/images/covers/nb-000014.svg', 'ongoing', 3.49, 199000, datetime('now', 'localtime', '-61 days')),
('NB-000015', 'Second Chance Empress', 4, 3, 'English', 'Betrayed and executed, the empress wakes up ten years in the past, determined to rewrite every mistake.', '/images/covers/nb-000015.svg', 'completed', 5.99, 187000, datetime('now', 'localtime', '-58 days')),
('NB-000016', 'The Quiet Apocalypse', 3, 8, 'English', 'One morning everyone in the city falls asleep except twelve people, and the sleepers have started to sleepwalk.', '/images/covers/nb-000016.svg', 'ongoing', 2.99, 143000, datetime('now', 'localtime', '-55 days')),
('NB-000017', 'Level One Farmer', 5, 7, 'English', 'Given the weakest class in a world of heroes, a young farmer discovers that crops can level up too.', '/images/covers/nb-000017.svg', 'ongoing', 2.49, 121000, datetime('now', 'localtime', '-52 days')),
('NB-000018', 'Paper Moons', 4, 10, 'English', 'A retired teacher and her teenage neighbour rebuild a run-down bookshop one shelf at a time.', '/images/covers/nb-000018.svg', 'completed', 1.49, 96000, datetime('now', 'localtime', '-49 days')),
('NB-000019', 'Gravity''s Edge', 2, 6, 'English', 'A pilot stranded at the edge of a black hole has to decide whether to save her crew or the colony that abandoned them.', '/images/covers/nb-000019.svg', 'ongoing', 4.49, 78000, datetime('now', 'localtime', '-46 days')),
('NB-000020', 'My Roommate Is a Dragon', 3, 9, 'English', 'A broke university student rents a cheap room, then learns the landlord is a dragon who is very bad at being human.', '/images/covers/nb-000020.svg', 'ongoing', 1.99, 54000, datetime('now', 'localtime', '-43 days'));

